/** one timer as read from its two states */
type TimerSource = { activeId: string; dataId: string; activeVal: unknown; dataVal: unknown };

/**
 * an item that wants a slot of a screensaver place (getData): shown (append), filler (hidden, fills free slots) or
 * hidden pinned indicator (keeps its slot empty)
 */
export type ScreensaverSlotCandidate<T = PageItem> = {
    /** order of the item */
    idx: number;
    payload: string;
    isFiller: boolean;
    item: T;
    /** slot of a pinned indicator (page item `pinnedSlot`) */
    pinnedSlot?: number;
    /** hidden pinned indicator without filler */
    hidden?: boolean;
};

/**
 * true for the config of a screensaver page, including cards of other adapter versions (screensaver4)
 *
 * @param config config of a page
 */
function isScreensaverConfig(
    config: NonNullable<pages.PageBase['config']>,
): config is pages.screensaverDataItemOptions {
    return typeof config.card === 'string' && config.card.startsWith('screensaver');
}

/**
 * Replaces a screensaver mode or card this adapter version does not know (branch or downgrade, e.g.
 * `tiles`) by the standard screensaver. The page gets its own copy of the config, so the given one -
 * and with it the stored configuration - stays as it is and the mode applies again after an upgrade.
 * Anything else is returned untouched, a config that is no screensaver stays an error of the constructor.
 *
 * @param options configuration of the page
 * @returns the page to use and, after a fallback, the rejected mode and card
 */
export function resolveScreensaverOptions(options: pages.PageBase): {
    options: pages.PageBase;
    rejected?: { mode: unknown; card: unknown };
} {
    const config = options.config;
    if (!config || !isScreensaverConfig(config)) {
        return { options };
    }
    const mode: unknown = config.mode;
    const card: unknown = config.card;
    if (globals.isScreenSaverMode(mode) && typeof card === 'string' && globals.isScreenSaverCardType(card)) {
        return { options };
    }
    return {
        options: { ...options, config: { ...config, card: 'screensaver', mode: 'standard' } },
        rejected: { mode, card },
    };
}

/**
 * TFT version from which on screensaver2/screensaver5 read the long press mask at the end of `weatherUpdate`
 * (`HMI/tools/indicator_long_press_mask.py`): only the marked indicators start the long press and let the clock blink.
 */
export const INDICATOR_LONG_PRESS_MASK_MIN_VERSION = '6.2.0';

/**
 * TFT version from which on the screensavers read field 5 of `notify~`, the background of the notification
 * (`HMI/tools/notify_background.py`). Fields 3/4 (headline/text color) are read by every TFT the adapter supports.
 */
export const NOTIFY_BACKGROUND_MIN_VERSION = '6.2.0';

/** The colors of the notification on the screensaver as the color theme holds them (a missing key is a string). */
export interface ScreensaverNotifyColors {
    /** headline (`tNotifyHead.pco`), field 3 */
    head: unknown;
    /** text (`tNotifyText.pco`), field 4 */
    text: unknown;
    /** background of both (`bco`), field 5 */
    background: unknown;
    /**
     * second background as RGB565, field 6: with field 5 the HMI alternates both every second (TFT 6.2.0+, web panel);
     * undefined = no blinking. Only sent together with the background.
     */
    blink?: number;
}

/**
 * `notify~<headline>~<text>~<headline color>~<text color>~<background>~<second background>` - the colors as RGB565. A
 * color that is no RGB stays empty (the HMI keeps its color, the background then is the one of the screensaver); empty
 * fields at the end are left out. The second background (blinking) only goes with a background.
 *
 * @param heading headline
 * @param text text
 * @param colors colors of the theme
 * @param withBackground true when the panel reads field 5 ({@link NOTIFY_BACKGROUND_MIN_VERSION}, web panel)
 * @returns the message
 */
export function screensaverNotifyPayload(
    heading: string,
    text: string,
    colors: ScreensaverNotifyColors,
    withBackground: boolean,
): string {
    const fields = [colors.head, colors.text, ...(withBackground ? [colors.background] : [])].map(c =>
        Color.isRGB(c) ? String(Color.rgb_dec565(c)) : '',
    );
    if (withBackground && fields[2] !== '' && colors.blink !== undefined) {
        fields.push(String(colors.blink));
    }
    while (fields.length > 0 && fields[fields.length - 1] === '') {
        fields.pop();
    }
    return tools.getPayload(tools.getPayloadRemoveTilde('notify', heading, text), ...fields);
}

/**
 * The long press mask of the indicator slots as the HMI reads it: bit (N-1) for indicator N (1 -> 1, 3 -> 4, 7 -> 64).
 *
 * @param supported per indicator slot as sent: true when its indicator has a long press
 * @returns the mask as a decimal number
 */
export function indicatorLongPressMask(supported: readonly boolean[]): number {
    let mask = 0;
    for (let i = 0; i < supported.length; i++) {
        if (supported[i]) {
            mask += 2 ** i;
        }
    }
    return mask;
}

/** Messages of the screensaver that are only sent when their content changed */
type FilteredMessage = 'weatherUpdate' | 'color' | 'statusUpdate' | 'notify';

/**
 * What a touch of the screensaver background (`bExit`) does, see {@link Screensaver.onExitTap}:
 * - `wake`: it only woke the dark display, the tap is done.
 * - `dismiss`: it takes the notification away (dismissible ones are dismissed), no navigation.
 * - `leave`: it leaves the screensaver, whatever the double click option says.
 * - `normal`: the usual way (timer tap, notification, gesture, double click).
 */
export type ScreensaverExitTap = 'wake' | 'dismiss' | 'leave' | 'normal';

